-- PT133-S2-Q25. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT133-S2-Q25$batch13$ AND q.stimulus=$batch13$In ancient Greece, court witnesses were not cross­ examined and the jury, selected from the citizenry, received no guidance on points of law; thus, it was extremely important for litigants to make a good impression on the jurors. For this reason, courtroom oratory by litigants is a good source of data on the common conceptions of morality held by the citizens of ancient Greece.$batch13$ AND q.prompt=$batch13$Which one of the following, if true, would most strengthen the argument?$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT133-S2-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch13$0352230f-ff1f-4b13-8932-7d1ac7ede622$batch13$) <> 3 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch13$0352230f-ff1f-4b13-8932-7d1ac7ede622$batch13$) <> 3 THEN RAISE EXCEPTION 'Explanation changed: PT133-S2-Q25'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Personality isn't morality. If jurors went by personality, the speeches would show what personalities jurors liked, not what the citizens believed was moral.$batch13$), ($batch13$C$batch13$, $batch13$If litigants thought jurors favored people whose professed morals matched their own, litigants would shape their speeches to the jurors' morals. Jurors were ordinary citizens, so the speeches would reflect common moral views.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT133-S2-Q25$batch13$ AND e.id=$batch13$0352230f-ff1f-4b13-8932-7d1ac7ede622$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
